class Frontend final : public gfsim::SimModule {
public:
  explicit Frontend(std::string instanceName, gfsim::WorkExecutor *executor = nullptr) : gfsim::SimModule(instanceName), pyc_implementation(std::make_shared<pyc_family_Frontend<1>>(std::move(instanceName), executor)) {
  }
  Frontend(const Frontend &) = delete;
  Frontend &operator=(const Frontend &) = delete;
  gfsim::wire<::rv32i_core::types::Machine> old;
  gfsim::wire<::rv32i_core::types::Machine> prior;
  gfsim::wire<::rv32i_core::types::Pins> original_io;
  gfsim::wire<::rv32i_core::types::ExecuteControl> ex_control;
  gfsim::wire<::rv32i_core::types::BusInputs> bus;
  gfsim::wire<::rv32i_core::types::Machine> result_0;
  gfsim::wire<::rv32i_core::types::Pins> result_1;
  void Work() override {
    pyc_implementation->old.element(0) = old;
    pyc_implementation->prior.element(0) = prior;
    pyc_implementation->original_io.element(0) = original_io;
    pyc_implementation->ex_control.element(0) = ex_control;
    pyc_implementation->bus.element(0) = bus;
    pyc_implementation->Work();
    result_0 = pyc_implementation->result_0.element(0);
    result_1 = pyc_implementation->result_1.element(0);
  }
  void Xfer() noexcept override { pyc_implementation->Xfer(); }
  void DiscardNext() noexcept override { pyc_implementation->DiscardNext(); }
  void Reset() noexcept override {
    pyc_implementation->old.element(0) = old;
    pyc_implementation->prior.element(0) = prior;
    pyc_implementation->original_io.element(0) = original_io;
    pyc_implementation->ex_control.element(0) = ex_control;
    pyc_implementation->bus.element(0) = bus;
    pyc_implementation->Reset();
  }
  bool HasWork() const noexcept override { return true; }
private:
  std::shared_ptr<pyc_family_Frontend<1>> pyc_implementation;
};
